package jurisdiction

import (
	_ "embed"
	"encoding/json"
	"sync"
)

// territories.json is generated by scripts/make-territories.sh from Unicode CLDR.
//
//go:embed territories.json
var territoriesJSON []byte

// Region is a UN M49 continent and the ISO 3166-1 countries it contains.
type Region struct {
	Code      string            `json:"code"`
	Name      map[string]string `json:"name"`
	Countries []string          `json:"countries"`
}

// Territory is the continent and country data.
type Territory struct {
	Source      string                       `json:"source"`
	Regions     []Region                     `json:"continents"`
	Names       map[string]map[string]string `json:"names"`
	continentOf map[string]string
}

var (
	once sync.Once
	tr   *Territory
)

// Territories returns the embedded continent and country data.
func Territories() *Territory {
	once.Do(func() {
		tr = &Territory{}
		if err := json.Unmarshal(territoriesJSON, tr); err != nil {
			panic("territories.json: " + err.Error())
		}
		tr.continentOf = map[string]string{}
		for _, r := range tr.Regions {
			for _, c := range r.Countries {
				tr.continentOf[c] = r.Code
			}
		}
	})
	return tr
}

// Continents returns the five continents: 002, 019, 142, 150, 009.
func (t *Territory) Continents() []Region { return t.Regions }

// CountryName returns the name of an ISO 3166-1 country, or "" if unknown.
func (t *Territory) CountryName(code, lang string) string { return t.Names[code][lang] }

// ContinentOf returns the M49 code of the continent holding a country.
func (t *Territory) ContinentOf(code string) string { return t.continentOf[code] }

// Region returns the continent with the given M49 code.
func (t *Territory) Region(code string) Region {
	for _, r := range t.Regions {
		if r.Code == code {
			return r
		}
	}
	return Region{}
}
